use agmp_native_protocol::{CapabilityIssueRequest,CapabilityLease};use anyhow::{bail,Result};use serde_json::Value;use sha2::{Digest,Sha256};use std::{collections::{BTreeMap,HashMap},sync::{Arc,Mutex},time::{SystemTime,UNIX_EPOCH}};use uuid::Uuid;
pub const FS_WRITE:&str="filesystem.write:workspace";pub const FS_MKDIR:&str="filesystem.mkdir:workspace";pub const PROCESS_START:&str="process.start:workspace";pub const DOWNLOAD:&str="network.download:workspace";pub const JAVA_ENSURE:&str="runtime.java.ensure";
#[derive(Clone)]pub struct CapabilityManager{leases:Arc<Mutex<HashMap<String,Entry>>>}#[derive(Clone)]struct Entry{lease:CapabilityLease,fingerprint:String,approval_hash:String,remaining:u8}
impl CapabilityManager{pub fn new()->Self{Self{leases:Arc::new(Mutex::new(HashMap::new()))}}pub fn issue(&self,r:CapabilityIssueRequest)->Result<CapabilityLease>{if r.run_id.trim().is_empty()||r.tool.trim().is_empty()||r.approval_hash.trim().is_empty(){bail!("capability requires run/tool/approval")};if !matches!(r.scope.as_str(),FS_WRITE|FS_MKDIR|PROCESS_START|DOWNLOAD|JAVA_ENSURE){bail!("unknown capability scope")};let now=ms();let lease=CapabilityLease{id:format!("LEASE-{}",Uuid::new_v4()),scope:r.scope.clone(),run_id:r.run_id.clone(),tool:r.tool.clone(),expires_at:now+r.ttl_ms.clamp(1_000,120_000).max(30_000),max_uses:1};self.leases.lock().unwrap().insert(lease.id.clone(),Entry{lease:lease.clone(),fingerprint:fingerprint(&r.payload),approval_hash:r.approval_hash,remaining:1});Ok(lease)}pub fn consume(&self,id:&str,scope:&str,run:&str,tool:&str,payload:&Value)->Result<()> {let mut all=self.leases.lock().unwrap();let e=all.get_mut(id).ok_or_else(||anyhow::anyhow!("capability missing or consumed"))?;if e.lease.expires_at<=ms(){bail!("capability expired")};if e.approval_hash.is_empty(){bail!("approval proof missing")};if e.lease.scope!=scope{bail!("capability scope mismatch")};if e.lease.run_id!=run{bail!("capability run mismatch")};if e.lease.tool!=tool{bail!("capability tool mismatch")};if e.fingerprint!=fingerprint(payload){bail!("capability request fingerprint mismatch")};e.remaining-=1;if e.remaining==0{all.remove(id);}Ok(())}}
fn fingerprint(v:&Value)->String{let mut h=Sha256::new();h.update(stable(v).as_bytes());hex::encode(h.finalize())}fn stable(v:&Value)->String{match v{Value::Object(m)=>{let b=m.iter().collect::<BTreeMap<_,_>>();format!("{{{}}}",b.into_iter().map(|(k,v)|format!("{}:{}",serde_json::to_string(k).unwrap(),stable(v))).collect::<Vec<_>>().join(","))},Value::Array(a)=>format!("[{}]",a.iter().map(stable).collect::<Vec<_>>().join(",")),_=>v.to_string()}}fn ms()->u64{SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_millis() as u64}
